import{_ as t}from"./chunks/d1f9fc25b3fc00dd.DfgUY9Lc.js";import{_ as a,o as i,c as d,aa as s}from"./chunks/framework.D7Mdgkg-.js";const f=JSON.parse(`{"title":"HTTP Surface and Live Actions","description":"Route classes, request lifecycle through gates, health endpoints and signed live actions in a Feluqa installation.","frontmatter":{"sidebarTitle":"HTTP & Live","icon":"radio","title":"HTTP Surface and Live Actions","description":"Route classes, request lifecycle through gates, health endpoints and signed live actions in a Feluqa installation.","summary":"Describes Feluqa's generated Axum HTTP routes, route classes, request lifecycle, security rules, and Live actions. It explains typed client-triggered server operations and incremental UI updates, and distinguishes implemented signed dispatch from remaining planned work.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":2,"status":"Partial","tags":["feluqa","http","axum","live-actions","routes"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"deployment/http-and-live-actions.md","filePath":"deployment/http-and-live-actions.md"}`),o={name:"deployment/http-and-live-actions.md"};function r(n,e,l,c,u,h){return i(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="http-surface-and-live-actions" tabindex="-1">HTTP Surface and Live Actions <a class="header-anchor" href="#http-surface-and-live-actions" aria-label="Permalink to &quot;HTTP Surface and Live Actions&quot;">​</a></h1><p>Feluqa serves HTTP through Axum. Routes are <strong>generated</strong> from attributes into a <code>const</code> route table; nothing is registered at boot by hand.</p><blockquote><p>Paths are illustrative defaults. Signed typed dispatch for live actions exists; the remaining items are tracked in F5.</p></blockquote><h2 id="route-classes" tabindex="-1">Route classes <a class="header-anchor" href="#route-classes" aria-label="Permalink to &quot;Route classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Example</th><th>Source</th><th>Protection</th></tr></thead><tbody><tr><td>System panel</td><td><code>/system/...</code></td><td>Built in</td><td>Privilege level + permission</td></tr><tr><td>Panels</td><td><code>/admin/customers/{id}/edit</code></td><td><code>#[panel]</code> + <code>#[resource]</code></td><td>Resource capabilities + policy</td></tr><tr><td>API handlers</td><td><code>GET /api/orders/{id}</code></td><td><code>#[feluqa::get(...)]</code></td><td><code>#[gate]</code> mandatory for writes</td></tr><tr><td>Live actions</td><td><code>POST /live/dispatch</code></td><td>Signed typed dispatch</td><td>Signature, replay protection, gate</td></tr><tr><td>Health</td><td><code>/healthz</code>, <code>/readyz</code></td><td>Built in</td><td>Public, no sensitive data</td></tr><tr><td>Assets</td><td><code>/assets/...</code></td><td><code>feluqa::asset!</code></td><td>Static, cacheable</td></tr></tbody></table><h2 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h2><p><img src="'+t+'" alt="Mermaid diagram"></p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>Every write route carries a <code>#[gate]</code>; <code>public</code> must be justified.</li><li>Error mapping: 401 unauthenticated, 403 denied, 404 for disabled features or invisible records.</li><li>Sessions use secure cookies and CSRF protection; the management listener can be bound separately from the public one.</li><li>The SDUI schema is filtered <strong>server-side</strong> before serialization.</li></ul><h2 id="live-actions" tabindex="-1">Live actions <a class="header-anchor" href="#live-actions" aria-label="Permalink to &quot;Live actions&quot;">​</a></h2><p>Live actions let the client trigger typed server actions and receive incremental UI updates.</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Status</th></tr></thead><tbody><tr><td>Signed typed dispatch</td><td>Exists</td></tr><tr><td>Shared replay protection (multi-node)</td><td>To do (F5)</td></tr><tr><td>Client reconciliation and focus handling</td><td>To do (F5)</td></tr><tr><td>Failure and reconnect tests</td><td>To do (F5)</td></tr></tbody></table>',12)])])}const g=a(o,[["render",r]]);export{f as __pageData,g as default};
